// Ad-level 60d is too big for one Meta call, so split into 7-day windows.
// The HTTP node runs once per item below, keeping each request small.
// Lower CHUNK to 3 if Meta still returns a transient 'Service temporarily unavailable'.
const CHUNK = 7;
const DAY = 86400000;
const f = d => `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
const end = new Date(Date.now() - DAY);       // yesterday
const start = new Date(Date.now() - 60*DAY);   // 60 days ago
const out = [];
let cur = new Date(start);
while (cur <= end) {
  const s = new Date(cur);
  const e = new Date(Math.min(cur.getTime() + (CHUNK-1)*DAY, end.getTime()));
  out.push({ json: { since: f(s), until: f(e) } });
  cur = new Date(e.getTime() + DAY);
}
return out;

